<template>
  <section v-if="tree" class="project-tree" :class="'pt-' + mode" aria-label="项目结构树">
    <header class="pt-header"><div class="pt-project"><h2 data-font="dynamic">{{ tree.project.projectName || '正在规划项目' }}</h2><div class="pt-versions"><span>{{ genTask.coreType }} {{ genTask.version }}</span><span>Java {{ tree.project.javaVersion }}</span></div></div><div v-lattice:two class="pt-status" :aria-busy="mode === 'draft' || mode === 'progress' && totals.done < totals.total"><div><span class="pt-status-dot"/><strong>{{ mode === 'draft' ? '正在规划结构' : mode === 'confirm' ? genTask.treeSessionStatus === 'failed' ? '等待修正' : '等待确认结构' : totals.done === totals.total ? '文件生成完成' : '正在生成文件' }}</strong></div><span>{{ mode === 'progress' ? '已完成 ' + totals.done + '/' + totals.total + ' · 契约 ' + totals.passed + '/' + totals.contracts : branches.length + ' 个模块 · ' + tree.nodes.length + ' 个文件' }}</span></div></header>
    <div ref="viewport" class="pt-map" tabindex="0" aria-label="可横向滚动的纵向分支树">
      <div class="pt-canvas">
        <div v-for="node in rootNodes" :key="node.id" class="pt-root" :class="{ 'has-open': openNodeIds.includes(node.id) }"><ProjectTreeNode :node="node" :mode="mode" :expanded="openNodeIds.includes(node.id)" :visited="visitedNodeIds.includes(node.id)" @toggle="toggleNode" @select="toggleFocus" @navigate="openDependency"/></div>
        <div class="pt-modules" :style="{ '--first-branch-half': branchExpanded(branches[0]?.id) ? '210px' : '112px', '--last-branch-half': branchExpanded(branches.at(-1)?.id) ? '210px' : '112px' }">
          <section v-for="module in branches" :key="module.id" class="pt-branch" :class="{ 'has-open': branchExpanded(module.id) }" :aria-label="module.title + '模块'">
            <button v-lattice:card type="button" class="pt-module" :class="{ selected: genTask.treeFocusIds.includes(module.id) }" :aria-pressed="mode === 'confirm' ? genTask.treeFocusIds.includes(module.id) : undefined" @click="toggleModule(module.id)"><span class="pt-module-kind"><Folder :size="16" aria-hidden="true"/>{{ module.kind === 'system' ? '系统模块' : module.kind === 'common' ? '公共模块' : '业务模块' }}<Check v-if="mode === 'confirm' && genTask.treeFocusIds.includes(module.id)" :size="13" aria-hidden="true"/></span><strong data-font="dynamic">{{ module.title }}</strong><code data-font="dynamic">{{ moduleSuffix(module.id) }}</code><span class="pt-module-role" data-font="dynamic">{{ module.responsibility }}</span><span class="pt-module-count">{{ mode === 'progress' ? progress[module.id].done + '/' + progress[module.id].total + ' 已完成' : progress[module.id].total + ' 个文件' }}</span></button>
            <div class="pt-nodes"><div v-for="node in tree.nodes.filter(node => node.moduleId === module.id)" :key="node.id" class="pt-file-branch"><ProjectTreeNode :node="node" :mode="mode" :expanded="openNodeIds.includes(node.id)" :visited="visitedNodeIds.includes(node.id)" @toggle="toggleNode" @select="toggleFocus" @navigate="openDependency"/></div><span v-if="!tree.nodes.some(node => node.moduleId === module.id)" class="pt-empty">等待添加文件</span></div>
          </section>
        </div>
      </div>
    </div>
    <details v-if="mode === 'draft'" class="pt-operations"><summary><span><GitBranch :size="13" aria-hidden="true"/>规划记录</span><span>第 {{ genTask.treeRound || 1 }} 轮 · {{ genTask.treeToolCallCount }} 次调用</span></summary><ol><li v-for="(operation, index) in genTask.treeOpsLog.slice(-20)" :key="index" data-font="dynamic">{{ operation }}</li></ol></details>
  </section>
</template>

<script setup lang="ts">
import { computed, nextTick, ref } from "vue";
import { Check, Folder, GitBranch } from "lucide-vue-next";
import { genTask } from "../logic/generateState";
import { moduleProgress, treeTotals } from "../logic/projectTree";
import ProjectTreeNode from "./ProjectTreeNode.vue";
const props = defineProps<{ mode: "draft" | "confirm" | "progress" }>();
const tree = computed(() => genTask.tree);
const rootNodes = computed(() => tree.value?.nodes.filter(node => node.moduleId === "_root") ?? []);
const branches = computed(() => tree.value ? [...tree.value.modules.filter(module => module.kind !== "system"), ...tree.value.modules.filter(module => module.kind === "system" && module.id !== "_root")] : []);
const viewport = ref<HTMLElement | null>(null);
const openNodeIds = ref<string[]>([]), visitedNodeIds = ref<string[]>([]);
const totals = computed(() => tree.value ? treeTotals(tree.value, genTask.files, genTask.nodeChecks) : { done: 0, total: 0, passed: 0, contracts: 0 });
const progress = computed(() => tree.value ? moduleProgress(tree.value, genTask.files) : {});
function branchExpanded(id?: string) { return !!id && !!tree.value?.nodes.some(node => node.moduleId === id && openNodeIds.value.includes(node.id)); }
function moduleSuffix(id: string) { return id === "_build" ? "Maven" : id === "_resources" ? "src/main/resources" : "." + id; }
function toggleFocus(id: string) { const index = genTask.treeFocusIds.indexOf(id); if (index >= 0) genTask.treeFocusIds.splice(index, 1); else genTask.treeFocusIds.push(id); }
function toggleModule(id: string) { if (props.mode === "confirm") toggleFocus(id); }
function toggleNode(id: string) { if (!visitedNodeIds.value.includes(id)) visitedNodeIds.value.push(id); const index = openNodeIds.value.indexOf(id); if (index >= 0) openNodeIds.value.splice(index, 1); else openNodeIds.value.push(id); }
async function openDependency(id: string) { if (!visitedNodeIds.value.includes(id)) visitedNodeIds.value.push(id); if (!openNodeIds.value.includes(id)) openNodeIds.value.push(id); await nextTick(); document.getElementById("node-details-" + id)?.closest("article")?.scrollIntoView({ behavior: "smooth", block: "center" }); }
</script>

<style scoped>
@layer legacy {
.project-tree{color:var(--text-primary);min-width:0}.pt-header{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:24px 0 26px;border-bottom:1px solid var(--line-soft)}.pt-project{min-width:0}.pt-project h2{margin:0 0 8px;font-size:25px;line-height:1.3;font-weight:500;overflow-wrap:anywhere}.pt-versions{display:flex;gap:14px;font-size:11px;color:var(--text-secondary)}.pt-status{padding:20px 24px;flex:none;min-width:172px;min-height:92px;--lattice-corner-inset:10px}.pt-status>div{display:flex;align-items:center;gap:8px;margin-bottom:7px}.pt-status strong{font-size:12px;font-weight:400}.pt-status>span{font-size:10px;color:var(--text-muted)}.pt-status-dot{display:inline-block;width:5px;height:5px;border-radius:50%;background:var(--oak);flex:none}.pt-status[aria-busy=true] .pt-status-dot{background:var(--cyan);animation:pt-pulse 1.5s infinite}
.pt-map{overflow-x:auto;padding:36px 16px 26px;outline-offset:-2px}.pt-canvas{display:flex;flex-direction:column;align-items:center;width:max-content;min-width:100%}.pt-root{position:relative;width:244px;flex:none;transition:width .28s}.pt-root.has-open{width:560px}.pt-root::after{content:'';position:absolute;top:100%;left:50%;height:40px;border-left:1px solid var(--line-warm)}.pt-modules{display:flex;align-items:flex-start;gap:40px;position:relative;margin-top:40px;padding-top:40px}.pt-modules::before{content:'';position:absolute;top:0;left:var(--first-branch-half);right:var(--last-branch-half);border-top:1px solid var(--line-warm);transition:left .28s,right .28s}.pt-branch{position:relative;width:224px;flex:none;min-width:0;transition:width .28s}.pt-branch.has-open{width:420px}.pt-branch::before{content:'';position:absolute;left:50%;top:-40px;height:40px;border-left:1px solid var(--line-warm)}.pt-module{position:relative;display:flex;flex-direction:column;align-items:flex-start;justify-content:center;gap:8px;width:100%;min-height:176px;min-width:0;padding:24px 28px;font:inherit;text-align:left;cursor:pointer;--lattice-corner-inset:14px}.pt-module::after{content:'';position:absolute;left:50%;top:100%;height:32px;border-left:1px solid var(--line-warm)}.pt-module-kind{display:flex;align-items:center;gap:8px;font-size:10px;color:var(--oak);width:100%;line-height:1.6}.pt-module-kind>svg:last-child:not(:first-child){margin-left:auto}.pt-module strong{font-size:14px;font-weight:400;line-height:1.7;overflow-wrap:anywhere}.pt-module code{color:var(--text-muted);font-size:10px;overflow-wrap:anywhere;line-height:1.6}.pt-module-role{font-size:11px;color:var(--text-secondary);overflow-wrap:anywhere;line-height:1.8}.pt-module-count{font-size:10px;color:var(--text-muted);line-height:1.6}.pt-module.selected{border-color:var(--oak);background:var(--oak-soft)}.pt-module:focus-visible{outline:1px solid var(--oak);outline-offset:3px}
.pt-nodes{position:relative;display:flex;flex-direction:column;gap:44px;min-width:0;margin-top:64px;padding-left:24px}.pt-nodes::after{content:'';position:absolute;left:0;top:-32px;width:50%;border-top:1px solid var(--line-warm)}.pt-file-branch{position:relative;min-width:0}.pt-file-branch::before{content:'';position:absolute;left:-24px;top:76px;width:24px;border-top:1px solid var(--line-warm)}.pt-file-branch::after{content:'';position:absolute;left:-24px;top:-44px;bottom:-44px;border-left:1px solid var(--line-warm)}.pt-file-branch:first-child::after{top:-32px}.pt-file-branch:last-child::after{bottom:auto;height:120px}.pt-file-branch:first-child:last-child::after{height:108px}.pt-empty{padding:20px;font-size:11px;color:var(--text-muted)}.pt-operations{margin:12px 24px 0;padding:14px;border:1px solid var(--line-soft);color:var(--text-secondary);font-size:11px}.pt-operations summary{display:flex;justify-content:space-between;gap:12px;cursor:pointer;list-style:none}.pt-operations summary>span{display:flex;align-items:center;gap:7px}.pt-operations summary>span:last-child{color:var(--text-muted);font-size:10px}.pt-operations ol{list-style:none;margin:12px 0 0;padding:0;display:grid;gap:5px;line-height:1.8}
@keyframes pt-pulse{50%{opacity:.25}}@media(prefers-reduced-motion:reduce){.pt-root,.pt-branch,.pt-modules::before{transition:none}.pt-status-dot{animation:none!important}}
}
</style>
